import cmath
import math
from fractions import Fraction

def show(z):
    return complex(round(z.real, 4) + 0.0, round(z.imag, 4) + 0.0)

def quadratic(a, b, k):
    D = b * b - 4 * a * k
    print(f"  u = cos theta: a = {a}, b = {b}, k = {k}, b^2 - 4ak = {D}")
    if D < 0:
        print("  no real u, so no solution")
        return
    r = math.isqrt(D)
    angles = []
    for u in sorted({Fraction(-b - r, 2 * a), Fraction(-b + r, 2 * a)}):
        if abs(u) > 1:
            print(f"  u = {u}: no angle, since cosine stays between -1 and 1")
        elif u == 1 or u == -1:
            beta = math.degrees(math.acos(u))
            print(f"  u = {u}: theta = {beta:.2f}")
            angles.append(round(beta, 2))
        else:
            beta = math.degrees(math.acos(u))
            print(f"  u = {u}: theta = {beta:.2f} or {360 - beta:.2f}")
            angles.append(round(beta, 2))
            angles.append(round(360 - beta, 2))
    print(f"  all solutions: {sorted(angles)}")

def ssa(A, a, b):
    s = b * math.sin(math.radians(A)) / a
    print(f"  sin B = b sin A / a = {s:.4f}")
    if s > 1 + 1e-9:
        print("  sin B > 1, so no triangle")
        return
    if abs(s - 1) < 1e-9:
        candidates = [90]
    else:
        B1 = math.degrees(math.asin(s))
        candidates = [B1, 180 - B1]
    found = 0
    for B in candidates:
        if A + B < 180 - 1e-9:
            found = found + 1
            print(f"  B = {B:.2f} fits, C = {180 - A - B:.2f}")
        else:
            print(f"  B = {B:.2f}: A + B = {A + B:.2f}, no room for C")
    print(f"  triangles: {found}")

def roots(s, phi, n):
    m = s ** (1 / n)
    print(f"  modulus {s}^(1/{n}) = {m:.4f}")
    for k in range(n):
        angle = (phi + 360 * k) / n
        print(f"  k = {k}: angle {angle:.2f}, root {show(cmath.rect(m, math.radians(angle)))}")

problems = [
    ("quadratic", [2, 3, 1]),
    ("ssa", [40, 7, 10]),
    ("roots", [8, 90, 3]),
    ("quadratic", [1, 0, -4]),
    ("ssa", [30, 5, 10]),
    ("roots", [27, 180, 3]),
    ("quadratic", [4, -4, 1]),
    ("ssa", [120, 7, 8]),
]
for i in range(len(problems)):
    kind, nums = problems[i]
    print(f"Problem {i + 1}: {kind} {nums}")
    if kind == "quadratic":
        quadratic(nums[0], nums[1], nums[2])
    elif kind == "ssa":
        ssa(nums[0], nums[1], nums[2])
    else:
        roots(nums[0], nums[1], nums[2])

